"""Contenido de los juegos de la Academia anavictoria.ia.

Ejecuta `python3 presentaciones/motor/construir.py` para regenerar los HTML.
Cada ronda: opciones (la correcta es `ok`), texto para el tablero (`b`), etiqueta (`tag`) y ficha (`info`).
"""

def O(t, why=""):
    return {"t": t, "why": why}

def I(chip, title, que, lista=None, ejemplo=None, error=None, lh=None):
    d = {"chip": chip, "title": title, "que": que}
    if lista: d["lista"] = lista
    if ejemplo: d["ejemplo"] = ejemplo
    if error: d["error"] = error
    if lh: d["lh"] = lh
    return d

